cases.source:
run flag: Bool -> Unit uses Console {
    [1, 2] => first
    first[0] -> println
    flag -> if {
        [3, 4] => nested
        nested[1] -> println
    }
    [5, 6] => last
    last[0] -> println
}

main {
    true -> run
    false -> run
}

early flag: Bool -> Int {
    [1, 2] => values
    flag -> if { values[0] -> return }
    values[1]
}

main {
    true -> early -> println
    false -> early -> println
}
